import{_ as a,o as t,c as i,aj as s}from"./chunks/framework.C6uXqnaX.js";const u=JSON.parse('{"title":"Creating an injectable service","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"tutorials/learn-angular/19-creating-an-injectable-service.md","filePath":"tutorials/learn-angular/19-creating-an-injectable-service.md"}'),n={name:"tutorials/learn-angular/19-creating-an-injectable-service.md"};function o(c,e,r,d,l,p){return t(),i("div",null,e[0]||(e[0]=[s(`<h1 id="creating-an-injectable-service" tabindex="-1">Creating an injectable service <a class="header-anchor" href="#creating-an-injectable-service" aria-label="Permalink to &quot;Creating an injectable service&quot;">​</a></h1><p>Dependency injection (DI) in Angular is one of the framework&#39;s most powerful features. Consider dependency injection to be the ability for Angular to <em>provide</em> resources you need for your application at runtime. A dependency could be a service or some other resources.</p><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>Learn more about <a href="/essentials/dependency-injection">dependency injection in the essentials guide</a>.</p></div><p>In this activity, you&#39;ll learn how to create an <code>injectable</code> service.</p><hr><p>One way to use a service is to act as a way to interact with data and APIs. To make a service reusable you should keep the logic in the service and share it throughout the application when it is needed.</p><p>To make a class eligible to be injected by the DI system, use the <code>@Service</code> decorator. For example:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> UserService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // methods to retrieve and return data</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The <code>@Service</code> decorator marks the class as a service and notifies the DI system that <code>UserService</code> can be accessed anywhere in your application. By default, Angular provides the service across your entire application, so you don&#39;t need to write any extra configuration.</p><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>By default, <code>@Service</code> provides the class at the root injector. If you want to provide it manually, for example, to scope it to a specific route or component, set <code>autoProvided: false</code>. Learn more in the <a href="/guide/di/creating-and-using-services#using-the-service-vs-injectable-decorator">guide on creating and using services</a>.</p></div><p>Alright, you try:</p><h3 id="_1-add-the-service-decorator" tabindex="-1">1. Add the <code>@Service</code> decorator <a class="header-anchor" href="#_1-add-the-service-decorator" aria-label="Permalink to &quot;1. Add the \`@Service\` decorator&quot;">​</a></h3><p>Update the code in <code>car.service.ts</code> by adding the <code>@Service()</code> decorator to the <code>CarService</code> class.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use the above example to find the correct syntax.</p></div><p>Well, done 👍 that service is now <code>injectable</code> and can participate in the fun. Now that the service is <code>injectable</code>, let&#39;s try injecting it into a component 👉</p>`,15)]))}const v=a(n,[["render",o]]);export{u as __pageData,v as default};
